module FS.Skia.UI.Build.SkillSync

open System.Text

// Feature 044 reframe (US1, FR-002/FR-004): SkillSyncCheck is no longer a six-slug
// byte-identity PEER check; it is a generation-currency check over the whole tree.
// `.agents/skills` is canonical; `.claude/skills` is generated by enumeration. All the
// real comparison logic lives in SkillTreeGen; this module is the gate-facing adapter
// (plan, currency, and the report/diagnostic rendering the SkillSyncCheck arm needs).

let planFromCanonical (canonical: SkillTreeGen.SkillFile list) = SkillTreeGen.plan canonical

let currency (plan: SkillTreeGen.SkillTreePlan) (derived: SkillTreeGen.SkillFile list) =
    SkillTreeGen.currency plan derived

let isCurrent (currency: SkillTreeGen.SkillCurrency) = SkillTreeGen.isCurrent currency

let renderReport (plan: SkillTreeGen.SkillTreePlan) (currency: SkillTreeGen.SkillCurrency) =
    let sb = StringBuilder()
    sb.AppendLine "# SkillSyncCheck" |> ignore
    sb.AppendLine "" |> ignore

    if SkillTreeGen.isCurrent currency then
        sb.AppendLine(
            sprintf
                "PASS: the generated `%s` tree is a current, byte-identical regeneration of the canonical `%s` source across all %d enumerated file(s) (coverage by enumeration, no allowlist)."
                SkillTreeGen.derivedRoot
                SkillTreeGen.canonicalRoot
                (List.length plan.Entries))
        |> ignore
    else
        sb.AppendLine(
            sprintf
                "FAIL: the generated `%s` tree is stale relative to the canonical `%s` source."
                SkillTreeGen.derivedRoot
                SkillTreeGen.canonicalRoot)
        |> ignore

        sb.AppendLine "" |> ignore

        if not (List.isEmpty currency.StaleSlugs) then
            sb.AppendLine(sprintf "- stale (bytes differ): %s" (String.concat ", " currency.StaleSlugs)) |> ignore

        if not (List.isEmpty currency.MissingDerived) then
            sb.AppendLine(sprintf "- missing derived: %s" (String.concat ", " currency.MissingDerived)) |> ignore

        if not (List.isEmpty currency.OrphanDerived) then
            sb.AppendLine(sprintf "- orphan derived (no canonical source): %s" (String.concat ", " currency.OrphanDerived)) |> ignore

    sb.ToString()

let renderFailureMessage (currency: SkillTreeGen.SkillCurrency) =
    match SkillTreeGen.currencyDrift currency with
    | None -> ""
    | Some message -> message
